import Foundation
import VaultKit
import XCTest

@testable import YubikeyKit
@testable import YubikeyKitMock

/// One signing session, end to end, through the real APDU layer and the real
/// ceremony — the shape the app uses, minus the screens.
///
/// The card is the simulated one, provisioned from the same deterministic entropy
/// the UI tests pass on the command line, and it returns the signature generated by
/// `tools/derive` for that card's key. So this test exercises the whole chain the
/// UI test does — read the card, check the manifest, bind the request, approve,
/// `VERIFY PW1` + `PSO:CDS`, recover the key, export the UR — in two seconds rather
/// than three minutes.
final class SigningEndToEndTests: XCTestCase {
    static let entropy = [UInt8](repeating: 0, count: 32)
    static let userPIN = Array("246810".utf8)
    static let adminPIN = Array("87654321".utf8)
    static let serial: UInt32 = 0x00DE_71A5
    /// The EIP-155 example, which is what the DEBUG sample request carries.
    static let payloadHex =
        "ec098504a817c800825208943535353535353535353535353535353535353535880de0b6b3a764000080018080"

    private func deterministicKey() throws -> (privateKey: SensitiveBytes, compressed: [UInt8], fingerprint: [UInt8], master: [UInt8]) {
        let words = try BIP39.mnemonic(fromEntropy: Self.entropy)
        let seed = try BIP39.seed(mnemonic: words)
        let master = try ExtendedPrivateKey.master(seed: seed)
        let leaf = try master.derived(try DerivationPath("m/44'/0'/0'/0/0"))
        let compressed = try leaf.publicKey()
        return (leaf.key, compressed, leaf.parentFingerprint, try master.fingerprint())
    }

    func testSigningThroughTheAPDULayer() async throws {
        let key = try deterministicKey()
        XCTAssertEqual(
            try EVMAddress.checksummed(fromPublicKey: key.compressed),
            SimulatedSigningVectors.address,
            "the simulated card must hold the key the generated signature belongs to"
        )

        // A card provisioned the way the ceremony leaves it: key in the signature
        // slot, PINs set, and a manifest describing that key.
        let transport = MockYubikeyTransport(transportName: "mock", serial: Self.serial, openPGPVersion: "3.4")
        let seeder = OpenPGPCard(transport: transport)
        try await seeder.open()
        try await seeder.select()
        try await seeder.verify(pin: OpenPGPPinDefaults.admin, reference: .admin, operation: .verifyAdminPIN)
        try await seeder.setPINs(userPIN: Self.userPIN, adminPIN: Self.adminPIN)
        try await seeder.importKey(
            slot: .signature,
            algorithm: .secp256k1,
            privateKey: key.privateKey,
            fingerprint: [UInt8](repeating: 0x22, count: 20),
            creationTime: Date(timeIntervalSince1970: 1_700_000_000),
            adminPIN: Self.adminPIN
        )
        let manifest = PairingManifest(
            cardSerial: withUnsafeBytes(of: Self.serial.bigEndian) { Array($0) },
            entries: [
                PairingManifest.Entry(
                    algorithm: .secp256k1,
                    publicKey: key.compressed,
                    chainCode: [UInt8](repeating: 0x11, count: 32),
                    parentFingerprint: key.fingerprint,
                    masterFingerprint: key.master,
                    originPath: try DerivationPath("m/44'/0'/0'/0/0"),
                    childrenPath: nil
                )
            ]
        )
        try await seeder.writePairingManifest(manifest.encoded(), adminPIN: Self.adminPIN)
        await seeder.close()

        let card = TransportSessionCard(makeTransport: { transport })
        let ceremony = SigningCeremony(card: card, transportDescription: "mock", appVersion: "test")

        let request = EthSignRequest(
            requestID: try Hex.decode("00112233445566778899aabbccddeeff"),
            signData: try Hex.decode(Self.payloadHex),
            dataType: .transaction,
            chainID: EVMQuantity(1),
            derivationPath: URKeyPath(
                path: try DerivationPath("m/44'/0'/0'/0/0"),
                sourceFingerprint: key.master.reduce(UInt32(0)) { $0 << 8 | UInt32($1) }
            ),
            address: nil,
            origin: "test"
        )
        // The request is taken first: it names the key, so the card read that follows can
        // ask for that one slot (amendment 33).
        try ceremony.accept(requestUR: try request.ur())
        try await ceremony.readCard()
        XCTAssertEqual(ceremony.card?.addressHex, SimulatedSigningVectors.address)
        ceremony.confirmChainID("1")
        try ceremony.verifyRequest()
        try ceremony.approve(acknowledgingDigestHex: ceremony.transaction!.signingDigest.hexString)

        let response = try await ceremony.sign(userPIN: Self.userPIN)
        XCTAssertEqual(
            response.hexString,
            SimulatedSigningVectors.signatures[ceremony.transaction!.signingDigest.hexString],
            "the card must answer with the generated signature"
        )
        try ceremony.verifySignature(cardResponse: response)
        let ur = try ceremony.exportSignature()
        let exported = try EthSignature(ur: ur)
        XCTAssertEqual(exported.requestID, try Hex.decode("00112233445566778899aabbccddeeff"))
        XCTAssertEqual(exported.recoveryValueBytes, [UInt8(SimulatedSigningVectors.legacyRecoveryValue)])
        XCTAssertEqual(transport.signatureRequestCount, 1, "one request, one PSO:CDS")
        // The counter moved by exactly one: one request, one signature. (A second
        // *session* may legitimately sign again — each one verifies the PIN afresh —
        // which is why the one-touch rule is enforced by the ceremony, not the card.)
        XCTAssertEqual(transport.signatureCounter, 1)
        XCTAssertNotNil(ur.string.range(of: "ur:eth-signature/"))
    }
}
